-- Fakt kartochkalarining ruscha matni — 6-partiya: jadidlar.
-- Abdulla Avloniy, Abdurauf Fitrat, Mahmudxo'ja Behbudiy,
-- Munavvarqori Abdurashidxonov.

-- ===== Abdulla Avloniy =====
UPDATE fact_cards SET topic_ru = 'Моё рождение', question_ru = 'Когда и где родился Абдулла Авлони?', fact_ru = 'Я родился 7 декабря 1878 года в Ташкенте, в семье ткача.' WHERE id = 251;
UPDATE fact_cards SET topic_ru = 'Моя учёба', question_ru = 'Какие языки Абдулла Авлони выучил самостоятельно?', fact_ru = 'В 1885–1895 годах я учился в мактабе и медресе. Арабский, персидский и русский языки выучил самостоятельно.' WHERE id = 252;
UPDATE fact_cards SET topic_ru = 'Мои газеты', question_ru = 'Какие газеты издавал Абдулла Авлони?', fact_ru = 'В 1907 году я издавал у себя дома газету «Шухрат»; в 1917 году выпускал газету «Туран».' WHERE id = 253;
UPDATE fact_cards SET topic_ru = 'Моя школа', question_ru = 'В какой махалле Ташкента Абдулла Авлони открыл школу в 1908 году?', fact_ru = 'В 1908 году я открыл новометодную школу в ташкентской махалле Мирабад, а в 1912 году устроил двухклассную школу в Дегрезе.' WHERE id = 254;
UPDATE fact_cards SET topic_ru = 'Благотворительное общество', question_ru = 'Какое общество создал Абдулла Авлони в 1909 году?', fact_ru = 'В 1909 году я создал благотворительное общество «Джамияти хайрия».' WHERE id = 255;
UPDATE fact_cards SET topic_ru = 'Мои учебники', question_ru = 'Какие учебники написал Абдулла Авлони?', fact_ru = 'Я написал учебники «Первый учитель» (1911), «Второй учитель» (1912) и «Школьный цветник» (1915).' WHERE id = 256;
UPDATE fact_cards SET topic_ru = '«Тюркский цветник»', question_ru = 'О чём книга Абдуллы Авлони «Тюркский цветник, или Нравственность»?', fact_ru = 'В 1913 году я издал книгу «Тюркский цветник, или Нравственность» — она учит детей добрым нравам.' WHERE id = 257;
UPDATE fact_cards SET topic_ru = 'Моя театральная труппа', question_ru = 'Когда Абдулла Авлони создал театральную труппу?', fact_ru = 'В 1913 году я создал театральную труппу, а в 1910–1916 годах перевёл и поставил ряд пьес.' WHERE id = 258;
UPDATE fact_cards SET topic_ru = 'Дипломатия', question_ru = 'В какой стране Абдулла Авлони работал политическим представителем?', fact_ru = 'В 1919–1920 годах я работал политическим представителем в Афганистане.' WHERE id = 259;
UPDATE fact_cards SET topic_ru = 'Мои последние годы', question_ru = 'Где Абдулла Авлони был профессором в конце жизни?', fact_ru = 'В 1930–1934 годах я был профессором и заведующим кафедрой в Среднеазиатском университете. Скончался 24 августа 1934 года.' WHERE id = 260;
UPDATE fact_cards SET topic_ru = 'Мои псевдонимы', question_ru = 'Под какими псевдонимами творил Абдулла Авлони?', fact_ru = 'Свои статьи и стихи я публиковал и под псевдонимами «Хиджран», «Набиль», «Индамас», «Шухрат».' WHERE id = 1430;
UPDATE fact_cards SET topic_ru = '«Первый учитель»', question_ru = 'Какую азбуку написал Абдулла Авлони для новометодных школ?', fact_ru = 'В 1912 году я написал для новометодных школ азбуку «Первый учитель». Её продолжением вышла и моя книга для чтения «Второй учитель».' WHERE id = 1431;
UPDATE fact_cards SET topic_ru = 'Мой поэтический сборник', question_ru = 'Как назывался поэтический сборник Абдуллы Авлони?', fact_ru = 'Свои стихи я издал в сборнике «Литература, или национальные стихи». С 1909 года он выходил несколькими выпусками.' WHERE id = 1432;
UPDATE fact_cards SET topic_ru = 'Моя комедия', question_ru = 'Какую комедию написал Абдулла Авлони?', fact_ru = 'В 1914 году я написал комедию «Легко ли быть адвокатом?». В ней через смех я показал пороки своего времени.' WHERE id = 1433;
UPDATE fact_cards SET topic_ru = 'Первый спектакль', question_ru = 'Какую драму поставила труппа «Туран» в Ташкенте в 1914 году?', fact_ru = 'В 1914 году наша труппа «Туран» поставила в Ташкенте драму Махмудходжи Бехбуди «Отцеубийца». Это стало большим событием в культурной жизни города.' WHERE id = 1434;
UPDATE fact_cards SET topic_ru = 'Профессорство', question_ru = 'Какого учёного звания удостоился Абдулла Авлони?', fact_ru = 'Впоследствии я преподавал будущим учителям в высших учебных заведениях и удостоился звания профессора.' WHERE id = 1435;
UPDATE fact_cards SET topic_ru = 'Моя память', question_ru = 'Чему сегодня присвоено имя Абдуллы Авлони?', fact_ru = 'Сегодня в нашей стране моим именем названы улицы и школы. Моё имя носит и ташкентский институт повышения квалификации педагогов.' WHERE id = 1436;

-- ===== Abdurauf Fitrat =====
UPDATE fact_cards SET topic_ru = 'Моё рождение', question_ru = 'Когда и где родился Абдурауф Фитрат?', fact_ru = 'Я родился в 1886 году в Бухаре, в семье интеллигентов.' WHERE id = 261;
UPDATE fact_cards SET topic_ru = 'Мой псевдоним', question_ru = 'Что означает псевдоним Фитрат?', fact_ru = 'В 1909–1913 годах я учился в Стамбульском университете; тогда же я взял псевдоним «Фитрат» — «знающий».' WHERE id = 262;
UPDATE fact_cards SET topic_ru = '«Сайха»', question_ru = 'Как назывался первый поэтический сборник Абдурауфа Фитрата?', fact_ru = 'В 1911 году вышел мой поэтический сборник «Сайха» («Зов»).' WHERE id = 263;
UPDATE fact_cards SET topic_ru = '«Спор»', question_ru = 'О чём произведение Абдурауфа Фитрата «Спор»?', fact_ru = 'В 1913 году в Стамбуле вышло моё произведение «Спор» — в нём дан спор старых и новых взглядов.' WHERE id = 264;
UPDATE fact_cards SET topic_ru = 'Мои драмы', question_ru = 'Какие драмы написал Абдурауф Фитрат?', fact_ru = 'Я написал драмы «Кровь», «Гробница Темура», «Огузхан», «Абулфайзхан» и «Арслан».' WHERE id = 265;
UPDATE fact_cards SET topic_ru = 'Моя наука о языке', question_ru = 'Какие труды по языку и литературе создал Абдурауф Фитрат?', fact_ru = 'Я создал труды «Правила литературы» и «Образцы староузбекской литературы»; мои учебники языка в 1925–1930 годах издавались пять раз.' WHERE id = 266;
UPDATE fact_cards SET topic_ru = 'Звание профессора', question_ru = 'Какое учёное звание Абдурауф Фитрат получил одним из первых?', fact_ru = 'Среди узбекских учёных я одним из первых получил звание профессора.' WHERE id = 267;
UPDATE fact_cards SET topic_ru = 'Моя музыкальная школа', question_ru = 'Какую школу основал Абдурауф Фитрат в 1921 году?', fact_ru = 'В 1921 году я основал Восточную музыкальную школу и руководил работой по записи мелодий Шашмакома нотами.' WHERE id = 268;
UPDATE fact_cards SET topic_ru = 'Моя книга о музыке', question_ru = 'Как называется трактат Абдурауфа Фитрата о музыке?', fact_ru = 'В 1927 году я издал трактат «Узбекская классическая музыка и её история».' WHERE id = 269;
UPDATE fact_cards SET topic_ru = 'Конец моей жизни', question_ru = 'Вместе с какими писателями Абдурауф Фитрат стал жертвой репрессий?', fact_ru = '4 октября 1938 года я стал жертвой репрессий вместе с Абдуллой Кадыри и Чулпаном.' WHERE id = 270;
UPDATE fact_cards SET topic_ru = '«Индийский путешественник»', question_ru = 'О чём произведение Абдурауфа Фитрата «Рассказ индийского путешественника»?', fact_ru = 'В произведении «Рассказ индийского путешественника» я описал жизнь Бухары глазами приезжего странника. Оно написано на персидском языке.' WHERE id = 1454;
UPDATE fact_cards SET topic_ru = '«Чагатайская беседа»', question_ru = 'Какое научно-литературное общество основал Абдурауф Фитрат?', fact_ru = 'Я возглавил создание в Ташкенте научно-литературного общества «Чагатайская беседа». В нём мы изучали вопросы языка и литературы.' WHERE id = 1455;
UPDATE fact_cards SET topic_ru = 'Моё наркомство просвещения', question_ru = 'На какой должности работал Абдурауф Фитрат в Бухарской республике?', fact_ru = 'В Бухарской Народной Советской Республике я работал наркомом просвещения. Я помогал молодёжи учиться за границей.' WHERE id = 1456;
UPDATE fact_cards SET topic_ru = '«Правила литературы»', question_ru = 'Какой учебник по теории литературы написал Абдурауф Фитрат?', fact_ru = 'В 1926 году я написал учебник «Правила литературы». В нём я просто объяснил науку о стихе и прозе.' WHERE id = 1457;
UPDATE fact_cards SET topic_ru = 'Моя история литературы', question_ru = 'Какой сборник по истории литературы составил Абдурауф Фитрат?', fact_ru = 'Собрав древние письменные памятники, я составил сборник «Образцы узбекской литературы». Так я открыл путь к изучению истории нашей литературы.' WHERE id = 1458;
UPDATE fact_cards SET topic_ru = 'Моё творчество на двух языках', question_ru = 'На каких языках творил Абдурауф Фитрат?', fact_ru = 'Свои произведения я писал на персидском и узбекском языках. Хорошо знал также арабский и турецкий.' WHERE id = 1459;
UPDATE fact_cards SET topic_ru = 'Моя реабилитация', question_ru = 'Как впоследствии были оценены имя и произведения Абдурауфа Фитрата?', fact_ru = 'Спустя годы после моей гибели имя моё было реабилитировано. Сегодня мои произведения переиздаются и изучаются в школах и университетах.' WHERE id = 1460;

-- ===== Mahmudxo'ja Behbudiy =====
UPDATE fact_cards SET topic_ru = 'Моё рождение', question_ru = 'Когда и где родился Махмудходжа Бехбуди?', fact_ru = 'Я родился в 1875 году в Самарканде, в семье богословов.' WHERE id = 231;
UPDATE fact_cards SET topic_ru = 'Мой путь к знанию', question_ru = 'Какие звания имел Махмудходжа Бехбуди?', fact_ru = 'Я глубоко изучил арабский язык. В 1902 году побывал в Мекке, а по возвращении получил звания ходжи и муфтия.' WHERE id = 232;
UPDATE fact_cards SET topic_ru = 'Мои поездки', question_ru = 'В каких городах Махмудходжа Бехбуди познакомился с татарской интеллигенцией?', fact_ru = 'Побывав в Казани, Уфе и Оренбурге, я познакомился с татарской интеллигенцией и её изданиями.' WHERE id = 233;
UPDATE fact_cards SET topic_ru = 'Мои статьи', question_ru = 'В каких изданиях публиковал статьи Махмудходжа Бехбуди?', fact_ru = 'С 1901 года я публиковал статьи в изданиях «Тараккий», «Шухрат», «Туран» и других.' WHERE id = 234;
UPDATE fact_cards SET topic_ru = 'Моя газета и журнал', question_ru = 'Какие газету и журнал основал Махмудходжа Бехбуди?', fact_ru = 'В 1912–1913 годах в родном городе я основал газету «Самарканд» и журнал «Ойина».' WHERE id = 235;
UPDATE fact_cards SET topic_ru = 'Мои учебники', question_ru = 'Какие учебники написал Махмудходжа Бехбуди?', fact_ru = 'Я написал учебники «Краткая общая география» (1903), «Книга для детей» (1904) и «Краткая история ислама» (1904).' WHERE id = 236;
UPDATE fact_cards SET topic_ru = 'Драма «Отцеубийца»', question_ru = 'Какое произведение стало первой драмой новой узбекской литературы?', fact_ru = 'В 1911 году я написал драму «Отцеубийца» — она стала первым драматическим произведением новой узбекской литературы.' WHERE id = 237;
UPDATE fact_cards SET topic_ru = '«Отцеубийца» на сцене', question_ru = 'Где впервые была поставлена драма «Отцеубийца»?', fact_ru = '«Отцеубийца» был поставлен 25 января 1914 года в Самарканде, затем показан в театрах Бухары и Ташкента.' WHERE id = 238;
UPDATE fact_cards SET topic_ru = 'Новая школа', question_ru = 'Какие школы пропагандировал Махмудходжа Бехбуди?', fact_ru = 'Я пропагандировал новометодные школы и учебные программы для них.' WHERE id = 239;
UPDATE fact_cards SET topic_ru = 'Конец моей жизни', question_ru = 'Когда и где был казнён Махмудходжа Бехбуди?', fact_ru = 'Я был казнён в 1919 году в городе Карши.' WHERE id = 240;
UPDATE fact_cards SET topic_ru = 'Вождь джадидов', question_ru = 'Одним из вождей какого движения был Махмудходжа Бехбуди?', fact_ru = 'Я был одним из вождей джадидов Туркестана — сторонников обновления и просвещения.' WHERE id = 1695;
UPDATE fact_cards SET topic_ru = 'Моя библиотека и издательство', question_ru = 'Что открыл Махмудходжа Бехбуди в Самарканде ради народного просвещения?', fact_ru = 'В Самарканде я открыл библиотеку и печатал книги в собственном издательстве — и всё это ради того, чтобы народ стал образованным.' WHERE id = 1696;
UPDATE fact_cards SET topic_ru = 'Мой знаменитый девиз', question_ru = 'Как звучит знаменитый девиз Махмудходжи Бехбуди?', fact_ru = 'Прославились мои слова: «Право берут, а не выпрашивают!» Ими я призывал народ знать свои права.' WHERE id = 1697;
UPDATE fact_cards SET topic_ru = 'Нужны четыре языка', question_ru = 'Какие языки призывал изучать Махмудходжа Бехбуди в статье «Не два, а четыре языка нужны»?', fact_ru = 'В статье «Не два, а четыре языка нужны» я призывал молодёжь изучать четыре языка — тюркский, персидский, арабский и русский.' WHERE id = 1698;
UPDATE fact_cards SET topic_ru = 'Туркестанская автономия', question_ru = 'В создании какого объединения, провозглашённого в Коканде в 1917 году, участвовал Махмудходжа Бехбуди?', fact_ru = 'Я деятельно участвовал в создании Туркестанской автономии, провозглашённой в Коканде в 1917 году.' WHERE id = 1699;
UPDATE fact_cards SET topic_ru = 'Город моего имени', question_ru = 'Какой город когда-то носил имя Махмудходжи Бехбуди?', fact_ru = 'В прошлом веке город Карши несколько лет носил моё имя — «Бехбуди».' WHERE id = 1700;
UPDATE fact_cards SET topic_ru = 'Моя память сегодня', question_ru = 'Как сегодня хранится память о Махмудходже Бехбуди в Узбекистане?', fact_ru = 'Сегодня в нашей стране моим именем названы многие улицы и школы.' WHERE id = 1701;

-- ===== Munavvarqori Abdurashidxonov =====
UPDATE fact_cards SET topic_ru = 'Моё рождение', question_ru = 'Когда и где родился Мунавваркари Абдурашидханов?', fact_ru = 'Я родился в 1878 году в ташкентской махалле Дархан, в семье мударриса. Моя мать Хосият-отын тоже была дочерью мударриса.' WHERE id = 241;
UPDATE fact_cards SET topic_ru = 'Моя учёба', question_ru = 'В каком медресе учился Мунавваркари Абдурашидханов?', fact_ru = 'В 1885–1890 годах я учился в бухарском медресе Мир-Араб. Выучив Коран целиком наизусть, я стал хафизом.' WHERE id = 242;
UPDATE fact_cards SET topic_ru = 'Моя джадидская школа', question_ru = 'Когда Мунавваркари Абдурашидханов открыл новометодную школу?', fact_ru = 'В 1901 году я открыл новометодную школу в собственном дворе.' WHERE id = 243;
UPDATE fact_cards SET topic_ru = '«Адиби аввал»', question_ru = 'Чем знаменит учебник «Адиби аввал»?', fact_ru = 'В 1907 году я написал учебник «Адиби аввал» — он стал одной из первых азбук на узбекском языке и применялся в школах всего Туркестана.' WHERE id = 244;
UPDATE fact_cards SET topic_ru = 'Мои другие учебники', question_ru = 'Какие ещё учебники создал Мунавваркари Абдурашидханов?', fact_ru = 'Я создал учебники «Адиб ус-сани» (1907), «Лик Земли» (1916–1917) и «Уроки узбекского языка» (1925–1926).' WHERE id = 245;
UPDATE fact_cards SET topic_ru = 'Мои газеты', question_ru = 'Какую газету основал Мунавваркари Абдурашидханов?', fact_ru = 'В 1906 году я основал газету «Хуршид»; работал также в газетах «Наджот» и «Кенгаш».' WHERE id = 246;
UPDATE fact_cards SET topic_ru = '«Садои Туркистон»', question_ru = 'В какой газете служил Мунавваркари Абдурашидханов?', fact_ru = 'В 1914–1915 годах я служил в газете «Садои Туркистон».' WHERE id = 247;
UPDATE fact_cards SET topic_ru = 'Университет', question_ru = 'Кто был первым ректором Туркестанского народного университета?', fact_ru = 'В апреле 1918 года я был избран основателем и ректором Туркестанского народного университета.' WHERE id = 248;
UPDATE fact_cards SET topic_ru = 'Моя работа в просвещении', question_ru = 'На каких должностях в сфере просвещения работал Мунавваркари Абдурашидханов?', fact_ru = 'Я работал наркомом просвещения города Ташкента, а в 1922 году — председателем Академцентра.' WHERE id = 249;
UPDATE fact_cards SET topic_ru = 'Конец моей жизни', question_ru = 'Когда было реабилитировано имя Мунавваркари Абдурашидханова?', fact_ru = 'В 1929 году меня арестовали, а в 1931 году казнили в Москве. Моё имя было реабилитировано в 1991 году.' WHERE id = 250;
UPDATE fact_cards SET topic_ru = 'Моя школа «Намуна»', question_ru = 'Под каким названием прославилась школа Мунавваркари Абдурашидханова?', fact_ru = 'Открытая мной новометодная школа прославилась под названием «Намуна». В неё приезжали учителя и из других городов, чтобы перенять способы преподавания.' WHERE id = 1716;
UPDATE fact_cards SET topic_ru = 'Звуковой метод', question_ru = 'По какому методу обучал детей Мунавваркари Абдурашидханов?', fact_ru = 'В своей школе я обучал детей «усули савтия», то есть звуковым методом. При нём дети осваивали чтение и письмо за несколько месяцев — намного быстрее, чем в старой школе.' WHERE id = 1717;
UPDATE fact_cards SET topic_ru = 'Общество «Туран»', question_ru = 'В работе какого просветительского общества в Ташкенте участвовал Мунавваркари Абдурашидханов?', fact_ru = 'Вместе с друзьями-джадидами я деятельно участвовал в работе ташкентского общества «Туран». Общество звало народ к просвещению через театральные представления и библиотеку.' WHERE id = 1718;
UPDATE fact_cards SET topic_ru = '«Шурои Исламия»', question_ru = 'Одним из руководителей какой организации был Мунавваркари Абдурашидханов в 1917 году?', fact_ru = 'Я был одним из руководителей организации «Шурои Исламия», созданной в Ташкенте в 1917 году. Мы стремились защищать права нашего народа.' WHERE id = 1719;
UPDATE fact_cards SET topic_ru = 'Студенты в Германии', question_ru = 'Чем занималось общество «Комак», созданное при участии Мунавваркари Абдурашидханова?', fact_ru = 'Чтобы молодёжь могла учиться за границей, мы с соратниками создали общество «Комак». В 1922 году группу туркестанских юношей отправили учиться в Германию.' WHERE id = 1720;
UPDATE fact_cards SET topic_ru = 'Книга моих воспоминаний', question_ru = 'Под каким названием изданы воспоминания Мунавваркари Абдурашидханова?', fact_ru = 'В последние годы жизни я писал воспоминания об истории джадидского движения. Позже они вышли книгой под названием «Из моих воспоминаний».' WHERE id = 1721;
UPDATE fact_cards SET topic_ru = 'Съезд о языке и правописании', question_ru = 'В каком съезде участвовал Мунавваркари Абдурашидханов в 1921 году?', fact_ru = 'В 1921 году в Ташкенте прошёл съезд, посвящённый узбекскому языку и правописанию. Я участвовал в нём и высказал свои мысли о развитии родного языка.' WHERE id = 1722;
